    // ── Smart format detection from prompt ──
    // ══ Campaign Shot: 1-click cinematic poster generator ══
    async function handleCampaignShot() {
        if (!csProductImage) { setCsError('Please upload a product image first'); return }
        setCsGenerating(true); setCsError(null); setCsResult(null)
        setCsSlots([null, null, null])
        const effectiveRatio = csAspectRatio === 'custom'
            ? `${csCustomW}:${csCustomH}`
            : csAspectRatio
        try {
            const payload = {
                brandId: activeBrand?._id,
                productImage: csProductImage,
                refImage: csRefImage || undefined,
                characterImage: csCharacterImage || undefined,
                moodPreset: csMoodPreset,
                aspectRatio: effectiveRatio,
                imageModel: csModel,
                productName: csProductName || undefined,
                brief: csBrief || undefined,
                primaryTagline: csPrimaryTagline || undefined,
                secondaryTagline: csSecondaryTagline || undefined,
                generateCopy: csCopyEnabled,
            }
            const result = await creativesAPI.campaignShot(payload)
            if (result.success && result.jobId) {
                // Polling logic for background job
                const jobId = result.jobId;
                let attempts = 0;
                const maxAttempts = 120; // 120 * 5s = 10 minutes max
                const pollInterval = setInterval(async () => {
                    attempts++;
                    if (attempts > maxAttempts) {
                        clearInterval(pollInterval);
                        setCsError('Generation timed out. Please try again.');
                        setCsGenerating(false);
                        return;
                    }
                    try {
                        const pollData = await creativesAPI.pollJob(jobId);
                        if (!pollData?.success) return;
                        const job = pollData.job;
                        
                        if (job.status === 'ready' || job.status === 'completed') {
                            clearInterval(pollInterval);
                            const creative = job.result?.creative || job;
                            const imageUrl = creative.imageUrl || job.imageUrl;
                            
                            if (!imageUrl) {
                                setCsError('Failed to retrieve generated image.');
                                setCsGenerating(false);
                                return;
                            }
                            
                            setCsResult({ 
                                imageUrl, 
                                taglines: creative.aiMeta?.taglines || [], 
                                productName: creative.aiMeta?.productName || '', 
                                prompt: creative.prompt, 
                                model: creative.aiMeta?.model || csModel, 
                                copy: creative.copy?.headline || null 
                            });
                            setCsGenerating(false);
                        } else if (job.status === 'failed') {
                            clearInterval(pollInterval);
                            setCsError(job.errorMessage || 'Campaign Shot generation failed');
                            setCsGenerating(false);
                        }
                    } catch (pollErr) {
                        console.error('Polling error:', pollErr);
                    }
                }, 5000);
            } else {
                setCsError(result.error || 'Generation failed to start')
                setCsGenerating(false)
            }
        } catch (err) {
            setCsError(err.message || 'Campaign Shot generation failed')
            setCsGenerating(false)
        }
    }

    function detectFormatFromPrompt(text) {

        const lower = text.toLowerCase()
        if (/instagram\s*(post|feed|grid)/i.test(lower)) return 'instagram-post'
        if (/story|stories|reel/i.test(lower)) return 'instagram-story'
        if (/facebook|fb\s*ad/i.test(lower)) return 'facebook-ad'
        if (/linkedin/i.test(lower)) return 'linkedin-post'
        if (/youtube|thumbnail|thumb/i.test(lower)) return 'youtube-thumb'
        if (/banner|hero|header|website/i.test(lower)) return 'banner'
        return null // keep current selection
    }


